    </Box>
  );
}
===== DATA =====
const initials = (name = "") => name.split(/\s+/).filter(Boolean).map((part) => part[0]).slice(0, 2).join("").toUpperCase() || "â€”";

const missingReason = (fields = []) => {
  if (fields.includes("bankCode") && fields.includes("bankAccountNumber")) return "No bank account information provided.";
  if (fields.includes("bankCode")) return "Bank code is missing.";
  return "Bank account number is missing.";
};

const normalizeRealEmployee = (employee) => {
  const suppliedStatus = employee.bankValidationStatus;
  const status = ["ready", "missing", "invalid"].includes(suppliedStatus)
    ? suppliedStatus
    : (!employee.bankCode || !employee.bankAccountNumber ? "missing" : "ready");
  return {
    ...employee,
    grossPay: Number(employee.grossPay || 0),
    cpfAmount: Number(employee.cpfAmount || 0),
    sdlAmount: Number(employee.sdlAmount || 0),
    approvedNetPay: Number(employee.approvedNetPay || 0),
    status,
    issueReason: employee.bankValidationReason || (status === "missing" ? missingReason(employee.missingFields) : ""),
    initials: initials(employee.employeeName),
  };
};

const normalizeLegacyMissingEmployee = (employee) => ({
  ...employee,
  grossPay: Number(employee.grossPay || 0),
  cpfAmount: Number(employee.cpfAmount || 0),
  sdlAmount: Number(employee.sdlAmount || 0),
  approvedNetPay: Number(employee.approvedNetPay || 0),
  bankCode: "",
  bankAccountNumber: "",
  status: "missing",
  issueReason: missingReason(employee.missingFields),
  initials: initials(employee.employeeName),
});

export const buildPaymentPreviewRows = ({ preview, missingDetails = [] }) => {
  if (Array.isArray(preview?.employees)) return preview.employees.map(normalizeRealEmployee);
  if (missingDetails.length) return missingDetails.map(normalizeLegacyMissingEmployee);
  return [];
};

export const getPreviewCounts = (rows) => {
  const missing = rows.filter((employee) => employee.status === "missing");
  const invalid = rows.filter((employee) => employee.status === "invalid");
  const ready = rows.filter((employee) => employee.status === "ready");
  return { missing, invalid, ready, excludedCount: missing.length + invalid.length };
};

export const matchesEmployeeSearch = (employee, search) => {
  const query = search.trim().toLowerCase();
  if (!query) return true;
  return [employee.employeeName, employee.employeeReference].some((value) => String(value || "").toLowerCase().includes(query));
};
===== STAFF API =====
import apiClient from "./client";

export const updateBankDetails = async (staffId, values) => (await apiClient.patch(`/staff/${staffId}/bank-details`, values)).data;
===== PAYMENT API =====
import apiClient from "./client";

export const getEligiblePeriods = async () => (await apiClient.get("/payments/eligible-periods")).data;
export const getPaymentPreview = async (payPeriodId) => (await apiClient.get("/payments/preview", { params: { payPeriodId } })).data;
export const generatePayment = async (payPeriodId) => (await apiClient.post("/payments/generate", { payPeriodId })).data;
export const getPaymentStatistics = async () => (await apiClient.get("/payments/dashboard/statistics")).data;
export const getPaymentBatches = async (params = {}) => (await apiClient.get("/payments", { params })).data;
export const getPaymentBatch = async (batchId) => (await apiClient.get(`/payments/${batchId}`)).data;
export const downloadPaymentFile = (batchId) => apiClient.get(`/payments/${batchId}/file`, { responseType: "blob" });
export const retryHrms = async (batchId) => (await apiClient.post(`/payments/${batchId}/retry-hrms`)).data;
export const cancelPaymentBatch = async (batchId, reason) => (await apiClient.patch(`/payments/${batchId}/cancel`, { reason })).data;
export const getBatchPayslips = async (batchId) => (await apiClient.get(`/payments/${batchId}/payslips`)).data;
===== VALIDATOR =====
const yup = require("yup");
const databaseUuid = () => yup.string().trim().matches(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i, "Must be a valid database UUID");

exports.generateSchema = yup.object({
    payPeriodId: databaseUuid().required(),
}).noUnknown(true);

exports.previewSchema = yup.object({ payPeriodId: databaseUuid().required() }).noUnknown(true);
exports.batchParamsSchema = yup.object({ batchId: databaseUuid().required() }).noUnknown(true);
exports.staffParamsSchema = yup.object({ staffId: databaseUuid().required() }).noUnknown(true);
exports.listSchema = yup.object({
    status: yup.string().oneOf(["generating", "generated", "hrms_sync_pending", "hrms_sync_failed", "completed", "cancelled"]).optional(),
    search: yup.string().trim().max(100).optional(),
    limit: yup.number().integer().min(1).max(100).optional(),
    offset: yup.number().integer().min(0).optional(),
}).noUnknown(true);

exports.cancelSchema = yup.object({
    reason: yup.string().trim().min(5).max(500).required(),
}).noUnknown(true);

exports.bankDetailsSchema = yup.object({
    bankCode: yup.string().trim().matches(/^[A-Za-z0-9-]{3,20}$/).required(),
    bankAccountNumber: yup.string().trim().matches(/^[A-Za-z0-9-]{5,50}$/).required(),
}).noUnknown(true);
===== APP ROUTES =====
const express = require("express");
const router = express.Router();
const authRoutes = require("./auth");
const paymentRoutes = require("./payments");
const staffRoutes = require("./staff");
const auditLogRoutes = require("./auditLogs");
const payslipRoutes = require("./payslips");

router.use("/auth", authRoutes);
// Payment APIs
router.use("/payments", paymentRoutes);
router.use("/staff", staffRoutes);
router.use("/audit-logs", auditLogRoutes);
router.use("/payslips", payslipRoutes);
module.exports = router;

