const { Sequelize } = require("sequelize");
const { types } = require("pg");
require("dotenv").config();

// Every timestamp column in this schema is `timestamp without time zone` (see
// 005_initial_schema.sql), and the app always writes them via `new Date()` /
// Sequelize's NOW default, whose UTC wall-clock numbers land in the column
// with no timezone tag. node-postgres's default parser for that Postgres
// type (OID 1114) reconstructs a JS Date by treating those naive numbers as
// the *server process's local* time, not UTC -- silently shifting every
// generated_at/created_at/etc. by the local UTC offset once read back out.
// Parsing it explicitly as UTC here makes the read side agree with how the
// value was written, with no schema, migration, or historical-data changes.
types.setTypeParser(types.builtins.TIMESTAMP, (value) => (
    value === null ? null : new Date(`${value.replace(" ", "T")}Z`)
));

const commonOptions = {
    dialect: "postgres",
    logging: false,
    dialectOptions: process.env.NODE_ENV === "production"
        ? { ssl: { require: true, rejectUnauthorized: false } }
        : {},
